function validate(input) {
  const [nums, operation] = input;
  if (operation !== 'Add' && operation !== 'String') return 'operation must be "Add" or "String".';
  if (!Array.isArray(nums) || nums.length !== (operation === 'Add' ? 2 : 1)) return '"Add" takes two arrays and "String" takes one.';
  for (const values of nums) {
    if (!Array.isArray(values) || values.length > 1000) return 'Each array holds at most 1000 integers.';
    if (!values.every(value => Number.isInteger(value) && value >= 0 && value <= 1000)) return 'Each element is an integer from 0 to 1000.';
  }
  return null;
}

