function adapt(input, solve, kit) {
  const [nums, operation] = input;
  const wrappers = nums.map(values => new solve(values));
  if (operation === 'Add') {
    const total = wrappers[0] + wrappers[1];
    kit.trace(`obj1 + obj2 gives ${JSON.stringify(total)}`);
    return total;
  }
  const text = String(wrappers[0]);
  kit.trace(`String(obj) gives ${JSON.stringify(text)}`);
  return text;
}

