class ArrayWrapper {
  constructor(nums) {
    this.nums = nums;
  }

  valueOf() {
    let total = 0;
    for (const value of this.nums) {
      total += value;
    }
    return total;
  }

  toString() {
    return `[${this.nums.join(',')}]`;
  }
}

