function ArrayWrapper(nums) {
  // One conversion hook for both cases: + asks with the hint "default", String() with "string".
  const values = nums.slice();
  this[Symbol.toPrimitive] = hint => {
    if (hint === 'string') return JSON.stringify(values);
    let total = 0;
    for (let i = 0; i < values.length; i++) total += values[i];
    return total;
  };
}

