function generate(rand, size) {
  const small = size === 'small';
  const operation = rand() < 0.5 ? 'Add' : 'String';
  const array = () => {
    const length = small ? Math.floor(rand() * 5) : 600 + Math.floor(rand() * 401);
    const high = rand() < 0.3 ? 3 : 1001;
    return Array.from({ length }, () => Math.floor(rand() * high));
  };
  return [operation === 'Add' ? [array(), array()] : [array()], operation];
}
